CREATE TABLE log(t); CREATE TABLE t4(a TEXT,b INTEGER,c REAL); INSERT INTO t4(rowid,a,b,c) VALUES(1,'8',8,8); CREATE TRIGGER t4bu BEFORE UPDATE ON t4 BEGIN INSERT INTO log VALUES(old.rowid||' '||typeof(old.rowid)||' '||old.a||' '||typeof(old.a)||' '||old.b||' '||typeof(old.b)||' '||old.c||' '||typeof(old.c)); INSERT INTO log VALUES(new.rowid||' '||typeof(new.rowid)||' '||new.a||' '||typeof(new.a)||' '||new.b||' '||typeof(new.b)||' '||new.c||' '||typeof(new.c)); END; CREATE TRIGGER t4au AFTER UPDATE ON t4 BEGIN INSERT INTO log VALUES(old.rowid||' '||typeof(old.rowid)||' '||old.a||' '||typeof(old.a)||' '||old.b||' '||typeof(old.b)||' '||old.c||' '||typeof(old.c)); INSERT INTO log VALUES(new.rowid||' '||typeof(new.rowid)||' '||new.a||' '||typeof(new.a)||' '||new.b||' '||typeof(new.b)||' '||new.c||' '||typeof(new.c)); END;